def transform(g):
    h,w=len(g),len(g[0])
    srows=[r for r in range(h) if all(g[r][c]==8 for c in range(w))]
    scols=[c for c in range(w) if all(g[r][c]==8 for r in range(h))]
    def blocks(seps,n):
        bs=[];s=0
        for x in seps+[n]:
            if x-s>1: bs.append((s,x))
            s=x+1
        return bs
    rb=blocks(srows,h);cb=blocks(scols,w)
    if not rb or not cb: return [r[:] for r in g]
    full_r=(rb[0][1]-rb[0][0]); full_c=(cb[0][1]-cb[0][0])
    dots={}
    for bi,(r0,r1) in enumerate(rb):
        for bj,(c0,c1) in enumerate(cb):
            for r in range(r0,r1):
                for c in range(c0,c1):
                    v=g[r][c]
                    if v not in (0,8): dots.setdefault(v,[]).append((bi,bj))
    cover={}
    for col,bl in dots.items():
        for i in range(len(bl)):
            for j in range(i+1,len(bl)):
                (a1,b1),(a2,b2)=bl[i],bl[j]
                if a1==a2:
                    for bj in range(min(b1,b2),max(b1,b2)+1):
                        if rb[a1][1]-rb[a1][0]==full_r and cb[bj][1]-cb[bj][0]==full_c:
                            cover.setdefault((a1,bj),set()).add(col)
                if b1==b2:
                    for bi in range(min(a1,a2),max(a1,a2)+1):
                        if rb[bi][1]-rb[bi][0]==full_r and cb[b1][1]-cb[b1][0]==full_c:
                            cover.setdefault((bi,b1),set()).add(col)
    out=[r[:] for r in g]
    for bi,(r0,r1) in enumerate(rb):
        for bj,(c0,c1) in enumerate(cb):
            cols=cover.get((bi,bj))
            if not cols: continue
            color = 6 if len(cols)>1 else next(iter(cols))
            for r in range(r0,r1):
                for c in range(c0,c1):
                    out[r][c]=color
    return out
'''
